def separate_paren_groups(paren_string: str) -> List[str]:
    """Return a list of top-level balanced parentheses groups from the input string."""
    groups = []
    depth = 0
    buffer = []
    for ch in paren_string:
        if ch == ' ':
            continue
        if ch == '(':
            if depth == 0:
                buffer = []  # start a new group
            depth += 1
        elif ch == ')':
            depth -= 1
        buffer.append(ch)
        if depth == 0 and buffer:
            groups.append(''.join(buffer))
    return groups

def truncate_number(number: float) -> float:
    """Return the decimal part of a positive floating-point number."""
    return number - int(number)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("mean_absolute_deviation requires at least one data point")
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    neg_inf = -10 ** 15
    # dp[x1][x2] holds best sum when both walkers have taken (x1-1)+(y1-1) steps
    prev = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    # Starting position (1,1) for both
    prev[1][1] = grid[1][1]
    # Iterate over steps s = x + y, starting from s=3 to 2*N
    for s in range(3, 2 * N + 1):
        cur = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        # x ranges within [1, N] and y = s - x must be within [1, N]
        min_x = max(1, s - N)
        max_x = min(N, s - 1)
        for x1 in range(min_x, max_x + 1):
            y1 = s - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(min_x, max_x + 1):
                y2 = s - x2
                if y2 < 1 or y2 > N:
                    continue
                best = prev[x1][x2]         # both came from left (1,1)
                if x1 > 1:
                    best = max(best, prev[x1 - 1][x2])     # first down, second left
                    if x2 > 1:
                        best = max(best, prev[x1 - 1][x2 - 1])  # both down
                if x2 > 1:
                    best = max(best, prev[x1][x2 - 1])  # first left, second down
                if best == neg_inf:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                cur[x1][x2] = best + add
        prev = cur
    return prev[N][N] if prev[N][N] != neg_inf else 0

def find_number_combinations():
    def is_valid(n):
        if n < 100 or n > 999:
            return False
        d = []
        for _ in range(3):
            d.append(n % 10)
            n //= 10
        if 0 in d:
            return False
        return len(set(d)) == 3

    result = []
    for a in range(123, 988):
        if not is_valid(a):
            continue
        b = 2 * a
        c = 3 * a
        if not (is_valid(b) and is_valid(c)):
            continue
        result.append((a, b, c))
    return result

def cantor_numbering(N: int) -> str:
    # Find diagonal d such that d(d+1)/2 >= N
    lo, hi = 1, 1
    while hi * (hi + 1) // 2 < N:
        hi <<= 1  # double hi
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * (mid + 1) // 2 >= N:
            hi = mid
        else:
            lo = mid + 1
    d = lo
    prev_total = (d - 1) * d // 2
    idx = N - prev_total  # 1-based index inside the diagonal
    if d % 2 == 0:
        numer = idx
        denom = d - idx + 1
    else:
        numer = d - idx + 1
        denom = idx
    return f"{numer}/{denom}"

def max_product(num_str: str, N: int, K: int) -> int:
    # If impossible to insert K multiplication signs
    if K >= N:
        return 0
    # dp[i][k] = max product for first i digits with k multiplication signs
    dp = [[None] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # empty product
    # Precompute integer values of all substrings to avoid repeated int conversion
    substr_val = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            substr_val[i][j] = val
    for i in range(1, N + 1):
        # No multiplication sign
        dp[i][0] = substr_val[0][i]
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # need at least k+1 digits to place k signs
            max_prod = None
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev is None:
                    continue
                prod = prev * substr_val[j][i]
                if (max_prod is None) or (prod > max_prod):
                    max_prod = prod
            dp[i][k] = max_prod
    return dp[N][K] if dp[N][K] is not None else 0

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Possible aisle positions (between rows/columns)
    horiz_positions = list(range(1, M))   # 1..M-1
    vert_positions = list(range(1, N))    # 1..N-1

    from itertools import combinations

    best_separated = -1
    best_horiz = []
    best_vert = []

    # Preprocess pairs for speed
    pairs = chatting_pairs

    def is_separated(p, horiz_set, vert_set):
        (x, y, p, q) = p
        if x != p:
            lo, hi = (x, p) if x < p else (p, x)
            for h in horiz_set:
                if lo < h < hi:
                    return True
        if y != q:
            lo, hi = (y, q) if y < q else (q, y)
            for v in vert_set:
                if lo < v < hi:
                    return True
        return False

    # Enumerate all combinations
    for horiz_combo in combinations(horiz_positions, K) if K > 0 else [()]:
        horiz_set = set(horiz_combo)
        for vert_combo in combinations(vert_positions, L) if L > 0 else [()]:
            vert_set = set(vert_combo)
            separated_count = 0
            for p in pairs:
                if is_separated(p, horiz_set, vert_set):
                    separated_count += 1
            if separated_count > best_separated:
                best_separated = separated_count
                best_horiz = list(horiz_combo)
                best_vert = list(vert_combo)

    # Build output strings
    horiz_str = ' '.join(map(str, sorted(best_horiz))) if K > 0 else ''
    vert_str = ' '.join(map(str, sorted(best_vert))) if L > 0 else ''
    return horiz_str, vert_str

