def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    result_parts = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        sign = ''
        if result_parts:
            sign = '-' if coeff < 0 else '+'
        else:
            if coeff < 0:
                sign = '-'
        abs_coef = abs(coeff)
        if degree == 0:
            coef_part = str(abs_coef)
        else:
            coef_part = '' if abs_coef == 1 else str(abs_coef)
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'
        result_parts.append(f"{sign}{coef_part}{var_part}")
    return ''.join(result_parts) if result_parts else '0'

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig
    if len(mapping) < 26:
        return "Failed"
    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])
    return "".join(decoded)

def largest_prime_factor(n: int) -> int:
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer `n` into `k` parts,
    where each part is at least `x` and the order of parts does not matter.
    """
    if k == 0:
        return 1 if n == 0 else 0
    m = n - k * x
    if m < 0:
        return 0
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

def count_coprime_pairs(x0: int, y0: int) -> int:
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if _gcd(i, j) == 1:
                if i == j:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

