def string_transformation(A: str, B: str, rules: list) -> int | str:
    # If already equal
    if A == B:
        return 0
    from collections import deque

    max_depth = 10
    queue = deque([(A, 0)])
    visited = {A}
    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue
        # try all rules
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_string = current[:idx] + tgt + current[idx + len(src):]
                if new_string == B:
                    return depth + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, depth + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    w = 2
    while i * i <= num:
        if num % i == 0:
            return False
        i += w
        w = 6 - w
    return True

