def max_herb_value(T: int, M: int, herbs: list) -> int:
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return max(dp)

def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    # Boolean DP array where dp[s] indicates whether sum s is achievable
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        # Update dp array from higher sums to lower to avoid reuse of the same item
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
    # Find the maximum achievable sum not exceeding V
    max_sum = next((s for s in range(V, -1, -1) if dp[s]), 0)
    return V - max_sum

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.lower()
    key_len = len(key)
    result = []
    for i, ch in enumerate(ciphertext):
        cipher_val = ord(ch.lower()) - 97
        key_val = ord(key[i % key_len]) - 97
        plain_val = (cipher_val - key_val + 26) % 26
        result.append(chr(plain_val + 97))
    return "".join(result)

def find_most_unhappy_day(schedule):
    max_excess = -1
    unhappy_day = 0
    for idx, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            excess = total - 8
            if excess > max_excess:
                max_excess = excess
                unhappy_day = idx
    return unhappy_day

def minimum_cost_to_merge_fruits(fruit_counts: list[int]) -> int:
    from heapq import heapify, heappop, heappush
    if len(fruit_counts) <= 1:
        return 0
    heapify(fruit_counts)
    total_cost = 0
    while len(fruit_counts) > 1:
        a = heappop(fruit_counts)
        b = heappop(fruit_counts)
        cost = a + b
        total_cost += cost
        heappush(fruit_counts, cost)
    return total_cost)

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    max_len = 0
    for i in range(n):
        cur_len = inc[i] + dec[i] - 1
        if cur_len > max_len:
            max_len = cur_len
    return n - max_len
